nextflow_process {
    name "Test Process VCF2MAF"

    process "VCF2MAF"
    script "../main.nf"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "vcf2maf"

    test("Run without VEP") {
        def vep_cache
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            vep_cache = extract(modules_testdata_base_path + 'genomics/homo_sapiens/genome/vep_cache_113.tar.gz').resolve('vep')
        }


        when {
            params {
                module_args = '--ncbi-build GRCh38 --species homo_sapiens --inhibit-vep'
            }
            process {
                """
                input[0] = [
                    [ id:'test'],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/gvcf/test.genome.vcf", checkIfExists: true)
                ]
                input[1] = file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genome.fasta", checkIfExists: true)
                input[2] = []
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    path(process.out.maf[0][1]).readLines()[5..131],
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() },
            )
        }
    }

    test("Run with VEP"){
        def vep_cache
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            vep_cache = extract(modules_testdata_base_path + 'genomics/homo_sapiens/genome/vep_cache_113.tar.gz').resolve('vep')
        }

        when {
            params {
                module_args = "--ncbi-build GRCh38 --species homo_sapiens"
            }
            process {
                """
                input[0] = [
                    [ id:'test'],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/gvcf/test.genome.vcf", checkIfExists: true)
                ]
                input[1] = [ file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genome.fasta", checkIfExists: true) ]
                input[2] = file('${vep_cache}')
                """
            }
        }

        then{
            assertAll(
                { assert process.success },
                { assert path(process.out.maf[0][1]).readLines().size() == 2 }, // no variants, only header lines
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("Run without VEP - stub") {

        options "-stub"

        when {
            params {
                module_args = ''
            }
            process {
                """
                input[0] = [
                    [ id:'test'],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/gvcf/test.genome.vcf", checkIfExists: true)
                ]
                input[1] = [ file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genome.fasta", checkIfExists: true) ]
                input[2] = []
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match()}
            )
        }
    }

    test("Run with VEP - stub"){

        options "-stub"

        when {
            params {
                module_args = ''
            }
            process {
                """
                input[0] = [
                    [ id:'test'],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/gvcf/test.genome.vcf", checkIfExists: true)
                ]
                input[1] = [ file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genome.fasta", checkIfExists: true) ]
                input[2] = []
                """
            }
        }

        then{
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match()}
            )
        }
    }

}

